SELECT CASE WHEN quantity >= 246 THEN 'high' WHEN quantity >= 35 THEN 'mid' ELSE 'low' END AS quantity_bucket, YEAR(last_restock) AS last_restock_year, MIN(last_restock) AS first_last_restock, MAX(last_restock) AS latest_last_restock, COUNT(DISTINCT quantity) AS unique_products FROM inventory WHERE store_id IN (3, 4) GROUP BY 1, 2 ORDER BY unique_products DESC, quantity_bucket ASC, last_restock_year ASC LIMIT 10;
